def revision_cost(old, new, insert, erase, replace):
    before = []
    for j in range(len(new) + 1):
        before.append(j * insert)
    for i in range(1, len(old) + 1):
        row = [i * erase]
        for j in range(1, len(new) + 1):
            best = before[j - 1]
            if old[i - 1] != new[j - 1]:
                best += replace
            add_cost = row[j - 1] + insert
            drop_cost = before[j] + erase
            if add_cost < best:
                best = add_cost
            if drop_cost < best:
                best = drop_cost
            row.append(best)
        before = row
    return before[-1]

